steps.action:
curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "
      {
        teams(filter: { name: { eq: \"Web\" } }) {
          nodes {
            id
            name
            workflowStates(filter: { name: { eq: \"Done\" }, type: { eq: \"winning\" } }) {
              nodes {
                id
                name
                issues(filter: {
                  assignee: {
                    name: { eq: \"Priya Nair\" }
                  },
                  completedAt: {
                    eq: \"2026-10-02T00:00:00.000Z\"
                  }
                }) {
                  nodes {
                    id
                    identifier
                    title
                    description
                    priority
                    assignee {
                      name
                    }
                    state {
                      name
                    }
                    completedAt
                  }
                }
              }
            }
          }
        }
      }
    '
  }'
